import { Interface } from "@ethersproject/abi";
import { CHAINS_ENUM } from "@debank/common";
import { decodeCalldata, DecodeCalldataResult, QuoteResult } from "../src/quote";
import { DEX_ENUM } from "../src/consts";
import { VurtoABI } from "../src/abi";
import { verifySdk } from "../src/verify";

const ROUTER = "0x15cb65b1c6026334a079e48241d6c8fa79df7784";
const USER = "0x000000000000000000000000000000000000dEaD";
const USDC = "0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913";
const WETH = "0x4200000000000000000000000000000000000006";
const CBBTC = "0xcbB7C0000aB88B473b1f5aFd9ef808440eed33Bf";
const POOL = "0x2626664c2603336E57B271c5C0b26F421741e481";
const MAX = "0x" + "f".repeat(64);

// Returned by POST https://swap.vurto.cc/gateway/v1/quote on Base, taker = USER.
const USDC_TO_WETH = "";
const ETH_TO_USDC = "";

const vurto = new Interface(VurtoABI);
const leg = (tokenIn: string, tokenOut: string, amountIn: string, minAmountOut: string, receiver: string) =>
  [POOL, tokenIn, tokenOut, amountIn, minAmountOut, receiver, "0x", "0"];
const base = (data: string, value = "0x0") => ({ from: USER, to: ROUTER, data, value, chainId: 8453 });

describe("vurto calldata decode", () => {
  it("encodes the two router entrypoints", () => {
    expect(vurto.getSighash("executeMultiSwap")).toBe("0xf4babee5");
    expect(vurto.getSighash("executeMultiSwapWithFee")).toBe("0xc9d7532b");
  });

  it("swap from ERC20 to ERC20, net minimum after the fee", () => {
    const expectResult: DecodeCalldataResult = {
      fromToken: USDC,
      fromTokenAmount: "100000000",
      toToken: WETH,
      minReceiveToTokenAmount: "37129824019451329",
      toTokenReceiver: USER,
    };
    expect(decodeCalldata(DEX_ENUM.VURTO, base(USDC_TO_WETH))).toEqual(expectResult);
  });

  it("swap from ETH to ERC20", () => {
    const expectResult: DecodeCalldataResult = {
      fromToken: "base",
      fromTokenAmount: "30000000000000000",
      toToken: USDC,
      minReceiveToTokenAmount: "79932373",
      toTokenReceiver: USER,
    };
    expect(decodeCalldata(DEX_ENUM.VURTO, base(ETH_TO_USDC, "0x6a94d74f430000"))).toEqual(expectResult);
  });

  it("two hops chained through the router read as one pair", () => {
    const data = vurto.encodeFunctionData("executeMultiSwapWithFee", [
      [leg(USDC, WETH, "100000000", "1", ROUTER), leg(WETH, CBBTC, MAX, "100000", USER)],
      [0, 30],
    ]);
    expect(decodeCalldata(DEX_ENUM.VURTO, base(data))).toEqual({
      fromToken: USDC,
      fromTokenAmount: "100000000",
      toToken: CBBTC,
      minReceiveToTokenAmount: "99970",
      toTokenReceiver: USER,
    });
  });

  it("a basket of independent legs can never match a pair quote", () => {
    const data = vurto.encodeFunctionData("executeMultiSwapWithFee", [
      [leg(USDC, WETH, "100000000", "1", USER), leg(WETH, CBBTC, "5", "1", USER)],
      [30, 30],
    ]);
    expect(decodeCalldata(DEX_ENUM.VURTO, base(data))?.fromTokenAmount).toBe("0");
  });

  it("executeMultiSwap charges the fixed 3 bps", () => {
    const data = vurto.encodeFunctionData("executeMultiSwap", [[leg(USDC, WETH, "100000000", "1000000", USER)]]);
    expect(decodeCalldata(DEX_ENUM.VURTO, base(data))?.minReceiveToTokenAmount).toBe("999700");
  });
});

describe("vurto verifySdk", () => {
  const quote = (data: string): QuoteResult => ({
    tx: { from: USER, to: ROUTER, data, value: "0" },
    fromToken: USDC,
    fromTokenAmount: "100000000",
    toToken: WETH,
    toTokenAmount: "37316406049699829",
    spender: ROUTER,
  });
  const run = (userAddress: string) =>
    verifySdk({
      chain: CHAINS_ENUM.BASE,
      dexId: DEX_ENUM.VURTO,
      slippage: 0.5,
      data: quote(USDC_TO_WETH),
      payTokenId: USDC,
      receiveTokenId: WETH,
      nativeTokenAddress: "base",
      chainId: 8453,
      userAddress,
    });

  it("passes router, spender, calldata and receiver for a live quote", () => {
    const r = run(USER);
    expect([r.routerPass, r.spenderPass, r.callDataPass, r.receiverPass]).toEqual([true, true, true, true]);
  });

  it("fails the receiver check when the output goes to someone else", () => {
    expect(run("0x1111111111111111111111111111111111111111").receiverPass).toBe(false);
  });
});
